const b = document.createElement('button'); b.className = 'ib'; b.id = 'bMundo'; b.type = 'button'; b.textContent = '🌍'; b.setAttribute('aria-label', 'Mundo'); b.style.cssText = 'position:fixed;left:max(14px,env(safe-area-inset-left));bottom:calc(env(safe-area-inset-bottom) + 298px);z-index:3;width:58px;height:58px;border-radius:50%;font-size:28px;box-shadow:0 4px 0 rgba(0,0,0,.25),0 6px 16px rgba(0,0,0,.25);display:none'; b.onclick = () => { if (!G.S) return; if (CAM.x > OC.x0 - 200) { openSheet('mundo'); return; } CAM.z = zMin(); CAM.x = 8500; CAM.y = WH / 2; clampCam(); toast(L('muFlyHint'), 3500); }; document.body.appendChild(b);
